css:
.log-body p { margin: 0 0 0.4em; }
.log-body p:last-child { margin-bottom: 0; }
.log-body ul, .log-body ol { margin: 0.3em 0; padding-left: 1.5em; }
.log-body pre { margin: 0.3em 0; white-space: pre-wrap; font-size: 0.9em; }
.log-mention { font-weight: 600; color: var(--log-accent); }
.log-audio { color: var(--log-muted); font-size: 0.9em; }
.pb { height: 0; }
.cu-text { margin: 0; white-space: pre-wrap; }
.log-node--message { margin: 0 0 calc(var(--log-gap, 0.8) * 1em); }
.log-node--message.log-merged { margin-top: calc(var(--log-gap, 0.8) * -0.7em); }
.log-body p { margin: 0 0 0.35em; }
.log-body img { display: block; max-width: 100%; max-height: 16em; margin: 0.3em 0; border-radius: 0.6em; }
.log-body blockquote { margin: 0.3em 0; padding-left: 0.7em; border-left: 3px solid var(--log-rule); color: var(--log-muted); }
.log-body code { padding: 0 0.25em; border-radius: 0.25em; background: rgba(0, 0, 0, 0.05); font-size: 0.9em; }
.bb { display: grid; grid-template-columns: calc(var(--log-avatarsize, 2.6) * 1em) 1fr; column-gap: 0.75em; align-items: start; color: var(--log-ink); }
.bb-av { grid-column: 1; grid-row: 1; position: relative; width: calc(var(--log-avatarsize, 2.6) * 1em); height: calc(var(--log-avatarsize, 2.6) * 1em); margin: 0.15em 0 0 0.25em; border-radius: 50%; overflow: hidden; background: var(--log-bubble); box-shadow: 0 0 0 2px var(--log-page-bg, #ffffff), 0 0 0 3.5px var(--log-speaker-color, var(--log-rule)); }
.bb-mono { display: block; height: 100%; padding: 0 0.12em; overflow: hidden; word-break: break-all; text-align: center; font-size: calc(var(--log-avatarsize, 2.6) * 0.36em); line-height: 2.78; font-weight: 700; color: var(--log-speaker-color, var(--log-accent)); }
.bb-av .bb-img { max-width: none; position: absolute; top: 0; left: 0; width: 100%; height: 100%; max-height: none; object-fit: cover; }
.bb-main { grid-column: 2; grid-row: 1; min-width: 0; }
:root[data-log-showavatar="false"] .bb { grid-template-columns: 1fr; }
:root[data-log-showavatar="false"] .bb-av { display: none; }
:root[data-log-showavatar="false"] .bb-main { grid-column: 1; }
.bb-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.15em 0.55em; margin: 0 0 0.3em 0.2em; line-height: 1.3; }
.bb-name { font-size: 0.95em; font-weight: 700; color: var(--log-speaker-color, var(--log-ink)); }
.bb-time { font-size: 0.72em; color: var(--log-muted); font-variant-numeric: tabular-nums; }
:root[data-log-showtime="false"] .bb-time { display: none; }
.bb-chip { padding: 0 0.55em; border: 1px solid var(--log-rule); border-radius: 1em; font-size: 0.68em; letter-spacing: 0.05em; color: var(--log-muted); }
.bb-bubble { width: fit-content; max-width: 100%; padding: 0.5em 0.9em 0.55em; border-radius: 0.3em calc(var(--log-radius, 1.1) * 1em) calc(var(--log-radius, 1.1) * 1em) calc(var(--log-radius, 1.1) * 1em); background: var(--log-bubble); box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08); color: var(--log-ink); }
.log-merged .bb-av { visibility: hidden; height: 0; margin-top: 0; }
.log-merged .bb-head { display: none; }
.log-continued .bb-bubble { border-top-left-radius: 0.3em; border-top-right-radius: 0.3em; }
.log-continues .bb-bubble { border-bottom-left-radius: 0.3em; border-bottom-right-radius: 0.3em; }
.bb-ooc .bb-av { opacity: 0.55; }
.bb-ooc .bb-name { color: var(--log-muted); }
.bb-ooc .bb-bubble { background: transparent; box-shadow: none; border: 1px dashed var(--log-rule); font-size: 0.9em; color: var(--log-muted); }
.bb-dice .bb-bubble { border-left: 3px solid var(--log-diceink); border-radius: 0.3em 0.7em 0.7em 0.3em; background: var(--log-dice); font-family: "SFMono-Regular", Consolas, "Noto Sans Mono CJK SC", monospace; font-size: 0.9em; }
.bb-chip--dice { border-color: var(--log-diceink); color: var(--log-diceink); }
.bb-sys { padding: 0.1em 0; text-align: center; }
.bb-sys-pill { display: inline-block; max-width: 88%; padding: 0.3em 1em; border-radius: 1em; background: var(--log-bubble); font-size: 0.8em; line-height: 1.5; color: var(--log-muted); }
.bb-sys-name { margin-right: 0.5em; font-weight: 700; color: var(--log-ink); }
.log-merged .bb-sys-name { display: none; }
.bb-sys-body { display: inline; }
.bb-sys-body p { display: inline; margin: 0; }
.bb-sys-body p + p::before { content: " · "; }
.bb-narr { padding: 0.2em 10%; text-align: center; font-size: 0.92em; line-height: 1.7; color: var(--log-muted); }
.hd { margin: 1.6em 0 1.1em; text-align: center; font-size: 0.9em; line-height: 1.4; background: linear-gradient(var(--log-rule), var(--log-rule)) center / 100% 1px no-repeat; break-after: avoid; }
.hd-chip { display: inline-block; max-width: 80%; padding: 0.3em 1.1em; border-radius: 2em; background: var(--log-ink); color: var(--log-page-bg, #ffffff); letter-spacing: 0.06em; }
[data-log-level="1"] .hd { margin-top: 2.2em; font-size: 1.1em; }
[data-log-level="1"] .hd-chip { padding: 0.45em 1.5em; background: var(--log-accent); }
[data-log-level="3"] .hd-chip { border: 1px solid var(--log-rule); background: var(--log-page-bg, #ffffff); color: var(--log-ink); font-weight: 600; }
.tr { margin: 1.1em 0; text-align: var(--log-style-align, center); font-size: 0.78em; color: var(--log-muted); background: linear-gradient(var(--log-rule), var(--log-rule)) center / 100% 1px no-repeat; }
.tr-label { display: inline-block; padding: 0.15em 0.9em; border: 1px solid var(--log-rule); border-radius: 1em; background: var(--log-page-bg, #ffffff); letter-spacing: 0.1em; }
.cv { min-height: calc(var(--log-content-height, 180mm) * 0.92); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0.5em; text-align: center; break-after: page; }
.cv-fig { margin: 0 0 1em; }
.cv-fig img { max-height: calc(var(--log-content-height, 180mm) * 0.45); border-radius: 1.4em; box-shadow: 0 0 0 4px var(--log-page-bg, #ffffff), 0 0 0 5.5px var(--log-accent); }
.cv-title { margin: 0; font-size: 1.9em; line-height: 1.25; color: var(--log-ink); }
.cv-sub { margin: 0; color: var(--log-muted); }
.cv-chip { margin-top: 1em; padding: 0.25em 1.1em; border-radius: 2em; background: var(--log-bubble); font-size: 0.78em; letter-spacing: 0.3em; color: var(--log-muted); }
.ip { margin: 1em 0; text-align: center; break-inside: avoid; }
.ip img { border-radius: 0.9em; box-shadow: 0 2px 10px rgba(15, 23, 42, 0.12); }
.ip figcaption { display: inline-block; margin-top: 0.5em; padding: 0.2em 0.9em; border-radius: 1em; background: var(--log-bubble); font-size: 0.8em; color: var(--log-muted); }
.qt { position: relative; margin: 1em 6%; padding: 0.9em 1.3em; border-radius: 1em; background: var(--log-bubble); text-align: var(--log-style-align, left); color: var(--log-ink); }
.qt::before { content: "“"; position: absolute; top: -0.1em; left: 0.25em; font-size: 2.4em; line-height: 1; color: var(--log-accent); opacity: 0.45; }
.log-style-italic .qt { font-style: italic; }
.pro { margin: 0 0 1.4em; padding: 0.9em 1.2em; border: 1px solid var(--log-rule); border-radius: 1em; break-inside: auto; }
.pro-h { display: inline-block; margin: 0 0 0.6em; padding: 0.15em 0.9em; border-radius: 1em; background: var(--log-accent); font-size: 0.8em; letter-spacing: 0.25em; color: var(--log-page-bg, #ffffff); }
.pro-b { color: var(--log-ink); }
.toc { break-after: page; }
.toc-h { margin: 0 0 0.9em; text-align: center; font-size: 1.3em; }
.toc .log-toc-item { margin-bottom: 0.35em; padding: 0.4em 0.9em; border-radius: 0.8em; background: var(--log-bubble); }
.toc .log-toc-page { color: var(--log-muted); }
.cu { margin: 1em 0; padding: 0.8em 1em; border: 1px solid var(--log-rule); border-radius: 1em; break-inside: avoid; }
.log-style-accent .cu { border: 2px solid var(--log-accent); }
.cu-title { margin-bottom: 0.3em; font-weight: 700; color: var(--log-accent); }
.cu-note { margin: 0.4em 0 0; font-size: 0.85em; color: var(--log-muted); }
.ph { width: 100%; display: flex; justify-content: center; gap: 0.6em; }
.ph-sec::before { content: "· "; }
.pf { width: 100%; text-align: center; }
.pf-num { display: inline-block; min-width: 2.4em; padding: 0.1em 0.8em; border-radius: 1em; background: var(--log-bubble); color: var(--log-muted); font-variant-numeric: tabular-nums; }
@media print {
  .bb-bubble, .ip img { box-shadow: none; }
  .bb-bubble { border: 0.5pt solid var(--log-rule); }
}
